<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, apiBlob, openEventSocket } from '../api/client'

type DS={id:string;name:string;type?:string}
type M={id:string;name:string;source_datasource_id:string;target_datasource_id:string;mode:string;status:string;paused_from_status?:string;progress:number;full_engine:string;cdc_engine:string;rollback_cdc_engine?:string;cdc_ddl_mode?:string;cdc_conflict_mode?:string;cdc_conflict_column?:string;post_load_ddl_mode?:string;sequence_synced_at?:string;speed_bytes_sec:number;target_throughput_mbps?:number;auto_throughput_enabled?:boolean;completion_sla_seconds?:number;controller_target_bytes_sec?:number;throughput_controller_reason?:string;adaptive_hotspot_splits?:number;adaptive_running_yields?:number;adaptive_topology_drains?:number;adaptive_topology_degraded_yields?:number;controller_auto_probe_pct?:number;controller_sla_headroom_pct?:number;controller_learning_samples?:number;speed_rows_sec?:number;eta_seconds?:number;sla_p95_eta_seconds?:number;sla_p99_eta_seconds?:number;sla_risk_level?:string;sla_risk_reason?:string;cdc_lag_ms:number;total_chunks:number;finished_chunks:number;rows_migrated:number;bytes_migrated:number;last_error?:string;validation_enabled:boolean;auto_create_table:boolean;parallelism?:number;effective_parallelism?:number;flow_control_level?:string;flow_control_reason?:string;cdc_spool_growth_bytes_sec?:number;cdc_spool_critical_eta_seconds?:number;validation_barrier_position_type?:string;validation_barrier_position_value?:string;validation_barrier_resource?:string;validation_barrier_captured_at?:string}
type TopologyPlacement={id:string;kind:string;labels?:Record<string,string>;address?:string;weight?:number}
type MT={id:string;engine?:string;source_schema:string;source_table:string;target_schema:string;target_table:string;primary_key:string;total_chunks:number;finished_chunks:number;rows_migrated:number;status:string;topology?:TopologyPlacement[];profile_bytes_per_sec?:number;profile_rows_per_sec?:number;recommended_chunk_rows?:number;performance_samples?:number;topology_performance?:Record<string,{bytes_per_sec?:number;rows_per_sec?:number;recommended_chunk_rows?:number;samples?:number;p95_duration_ms?:number;p99_duration_ms?:number;health?:string;slow_streak?:number;good_streak?:number;recovery_concurrency_cap?:number;health_changed_at?:string;last_probe_at?:string}>}
type Chunk={id:string;table_id:string;chunk_no:number;split_type:string;start:number;end:number;start_cursor_json?:string;end_cursor_json?:string;cursor_json?:string;partition_name?:string;hash_bucket?:number;hash_buckets?:number;custom_where?:string;status:string;worker_id?:string;rows_written:number;retry_count:number;last_error?:string;last_read_ms?:number;last_write_ms?:number;last_batch_rows?:number;backpressure_level?:string;placement_hint?:Record<string,string>;topology_id?:string;topology_kind?:string}
type Precheck={name:string;level:string;message:string}
type Validation={id:string;chunk_id:string;status:string;source_rows:number;target_rows:number;source_checksum:string;target_checksum:string;last_error?:string}
type CDC={id:string;direction?:string;position_type?:string;position_value?:string;lag_ms:number;events_total?:number;events_pending?:number;recorded_at:string}
type CDCSpool={pending_transactions:number;pending_events:number;pending_bytes:number;first_position?:string;last_position?:string;storage_backend?:string;storage_level?:string;storage_capacity_bytes?:number;storage_used_bytes?:number;storage_free_bytes?:number;storage_used_pct?:number}
type DLQ={id:string;task_id:string;direction:string;position_type?:string;position_value?:string;resource?:string;last_error:string;retry_count:number;status:string;created_at:string;updated_at:string;resolved_at?:string}
type Conflict={id:string;task_id:string;direction:string;source_schema:string;source_table:string;key_fingerprint:string;policy:string;decision:string;source_version?:string;target_version?:string;position_type?:string;position_value?:string;created_at:string}
type EngineJob={id:string;task_id:string;kind:string;direction:string;engine:string;status:string;worker_id?:string;retry_count:number;last_error?:string;started_at?:string;updated_at:string}
type TaskLog={id:string;task_id:string;worker_id?:string;table_id?:string;chunk_id?:string;level:string;message:string;created_at:string}
type AssessmentFinding={object_type:string;source_object:string;target_object?:string;level:string;code:string;message:string}
type Assessment={task_id:string;compatible:number;warnings:number;unsupported:number;can_start:boolean;findings:AssessmentFinding[];assessed_at:string}
type SchemaObject={schema:string;name:string;type:string;related_to?:string;ddl?:string;definition?:string;dependencies?:string[];dependencies_known?:boolean;binding_known?:boolean}
type SchemaObjectPlanItem={source:SchemaObject;target_schema:string;target_name:string;target_related_to?:string;target_exists:boolean;action:string;reason:string}
type SchemaObjectPlan={task_id:string;safe_actions:number;manual:number;skipped:number;items:SchemaObjectPlanItem[];planned_at:string}
type SchemaObjectApplyResult={task_id:string;applied:number;skipped:number;failed:number;items:Array<{type:string;source_schema:string;name:string;target_schema:string;status:string;message?:string}>}

const items=ref<M[]>([]),sources=ref<DS[]>([]),dialog=ref(false),detailDialog=ref(false)
const detailTask=ref<M|null>(null),detailTables=ref<MT[]>([]),detailChunks=ref<Chunk[]>([]),prechecks=ref<Precheck[]>([]),assessment=ref<Assessment|null>(null),schemaObjectPlan=ref<SchemaObjectPlan|null>(null),validations=ref<Validation[]>([]),cdc=ref<CDC[]>([]),cdcSpool=ref<CDCSpool>({pending_transactions:0,pending_events:0,pending_bytes:0}),dlq=ref<DLQ[]>([]),conflicts=ref<Conflict[]>([]),engineJobs=ref<EngineJob[]>([]),taskLogs=ref<TaskLog[]>([])
const activeTab=ref('tables')
const tableMappingsJson=ref('')
const workerSelectorJson=ref('')
const rateWindowsJson=ref('')
const transformRulesJson=ref('')
const form=reactive({name:'',source_datasource_id:'',target_datasource_id:'',mode:'FULL',cdc_ddl_mode:'REJECT',cdc_conflict_mode:'SOURCE_WINS',cdc_conflict_column:'',chunk_rows:100000,batch_rows:500,parallelism:4,max_retries:3,auto_create_table:true,validation_enabled:true,validation_mode:'CHUNK_CHECKSUM',post_load_ddl_mode:'INDEXES',read_limit_mbps:0,write_limit_mbps:0,target_throughput_mbps:0,auto_throughput_enabled:false,completion_sla_seconds:0,rows_limit_per_sec:0,qps_limit:0,rate_limit_timezone:'Local',worker_affinity:'PREFERRED'})
let timer:number|undefined
let socket:WebSocket|undefined
const dsMap=computed(()=>Object.fromEntries(sources.value.map(x=>[x.id,x.name])))
async function load(){items.value=await api('/api/v1/migrations')}
async function loadDS(){sources.value=await api('/api/v1/datasources')}
async function create(){try{const payload:any={...form};if(tableMappingsJson.value.trim()){payload.tables=JSON.parse(tableMappingsJson.value)};if(workerSelectorJson.value.trim()){payload.worker_selector=JSON.parse(workerSelectorJson.value)};if(rateWindowsJson.value.trim()){payload.rate_limit_windows=JSON.parse(rateWindowsJson.value)};if(transformRulesJson.value.trim()){payload.transform_rules=JSON.parse(transformRulesJson.value)};await api('/api/v1/migrations',{method:'POST',body:JSON.stringify(payload)});dialog.value=false;await load()}catch(e:any){ElMessage.error(e.message)}}
async function action(id:string,a:string,body?:any){try{await api(`/api/v1/migrations/${id}/${a}`,{method:'POST',body:body?JSON.stringify(body):undefined});await load();if(detailTask.value?.id===id)await detail(items.value.find(x=>x.id===id)||detailTask.value)}catch(e:any){ElMessage.error(e.message)}}
async function detail(row:M){detailTask.value=row;const [tables,chunks,checks,assess,objPlan,vals,positions,spool,deadLetters,conflictItems,jobs,logs]=await Promise.all([api<MT[]>(`/api/v1/migrations/${row.id}/tables`),api<Chunk[]>(`/api/v1/migrations/${row.id}/chunks`),api<Precheck[]>(`/api/v1/migrations/${row.id}/precheck`).catch(()=>[]),api<Assessment>(`/api/v1/migrations/${row.id}/assessment`).catch(()=>null),api<SchemaObjectPlan>(`/api/v1/migrations/${row.id}/schema-objects/plan`).catch(()=>null),api<Validation[]>(`/api/v1/migrations/${row.id}/validations`).catch(()=>[]),api<CDC[]>(`/api/v1/migrations/${row.id}/cdc`).catch(()=>[]),api<CDCSpool>(`/api/v1/migrations/${row.id}/cdc/spool`).catch(()=>({pending_transactions:0,pending_events:0,pending_bytes:0})),api<DLQ[]>(`/api/v1/migrations/${row.id}/cdc/dlq`).catch(()=>[]),api<Conflict[]>(`/api/v1/migrations/${row.id}/cdc/conflicts`).catch(()=>[]),api<EngineJob[]>(`/api/v1/migrations/${row.id}/engine-jobs`).catch(()=>[]),api<TaskLog[]>(`/api/v1/migrations/${row.id}/logs?limit=500`).catch(()=>[])]);detailTables.value=tables;detailChunks.value=chunks;prechecks.value=checks;assessment.value=assess;schemaObjectPlan.value=objPlan;validations.value=vals;cdc.value=positions;cdcSpool.value=spool;dlq.value=deadLetters;conflicts.value=conflictItems;engineJobs.value=jobs;taskLogs.value=logs;detailDialog.value=true}
async function drainSpool(){if(!detailTask.value)return;try{const stats=await api<CDCSpool>(`/api/v1/migrations/${detailTask.value.id}/cdc/spool/drain`,{method:'POST'});cdcSpool.value=stats;ElMessage.success(stats.pending_transactions?`已执行 Drain，剩余 ${stats.pending_transactions} 个事务`:'CDC Spool 已排空')}catch(e:any){ElMessage.error(e.message)}}
async function downloadValidationReport(format:'json'|'html'|'pdf'|'manifest'){if(!detailTask.value)return;try{const path=format==='manifest'?`/api/v1/migrations/${detailTask.value.id}/validation-report/manifest`:`/api/v1/migrations/${detailTask.value.id}/validation-report?format=${format}`;const item=await apiBlob(path);const url=URL.createObjectURL(item.blob);const a=document.createElement('a');a.href=url;a.download=item.filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);ElMessage.success(item.sha256?`报告已生成，SHA-256 ${item.sha256.slice(0,16)}…`:'报告已生成')}catch(e:any){ElMessage.error(e.message)}}
async function archiveValidationReport(){if(!detailTask.value)return;try{const res=await api<{uri:string;committed:boolean;manifest_sha256?:string;registry?:{public_key_fingerprint_sha256?:string}}>(`/api/v1/migrations/${detailTask.value.id}/validation-report/archive`,{method:'POST'});ElMessage.success(res.committed?`验收报告已归档：${res.uri}${res.manifest_sha256?`，Manifest ${res.manifest_sha256.slice(0,16)}…`:''}`:'验收报告归档未完成')}catch(e:any){ElMessage.error(e.message)}}
async function downloadValidationPublicKey(){try{const item=await apiBlob('/api/v1/validation-report/public-key');const url=URL.createObjectURL(item.blob);const a=document.createElement('a');a.href=url;a.download=item.filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);ElMessage.success(item.fingerprint?`验签公钥已下载，指纹 ${item.fingerprint.slice(0,16)}…`:'验签公钥已下载')}catch(e:any){ElMessage.error(e.message)}}
async function showValidationArchiveRegistry(){if(!detailTask.value)return;try{const r=await api<any>(`/api/v1/migrations/${detailTask.value.id}/validation-report/archive`);await ElMessageBox.alert(`URI: ${r.uri}\nManifest SHA-256: ${r.manifest_sha256}\nEvidence: ${r.evidence_digest}\nKey: ${r.public_signature_key_id||'-'}\nFingerprint: ${r.public_key_fingerprint_sha256||'-'}\nObject Lock: ${r.object_lock_mode||'OFF'} ${r.retain_until||''}`,'验收报告归档登记',{confirmButtonText:'关闭'})}catch(e:any){ElMessage.error(e.message)}}
async function replayDLQ(item:DLQ){if(!detailTask.value)return;try{const res:any=await api(`/api/v1/migrations/${detailTask.value.id}/cdc/dlq/${item.id}/replay`,{method:'POST'});ElMessage.success(res?.duplicate?'该位点已确认，无需重复写入':`重放成功，应用 ${res?.applied||0} 个事件`);await detail(detailTask.value)}catch(e:any){ElMessage.error(e.message)}}
async function resolveCommit(item:DLQ,decision:'COMMITTED'|'NOT_COMMITTED'){if(!detailTask.value)return;try{const msg=decision==='COMMITTED'?'确认目标事务已经提交？QMigration 将只推进源位点，不会再次写目标。':'确认目标事务没有提交？QMigration 将立即对保留的事务执行一次受控重放。';await ElMessageBox.confirm(msg,'确认 COMMIT 结果',{type:'warning'});await api(`/api/v1/migrations/${detailTask.value.id}/cdc/dlq/${item.id}/resolve-commit`,{method:'POST',body:JSON.stringify({decision})});ElMessage.success(decision==='COMMITTED'?'已按已提交处理，位点已推进':'已确认未提交并完成受控重放');await detail(detailTask.value)}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e?.message||String(e))}}
async function applySafeSchemaObjects(){if(!detailTask.value||!schemaObjectPlan.value?.safe_actions)return;try{await ElMessageBox.confirm(`将执行 ${schemaObjectPlan.value.safe_actions} 个安全 Schema 对象动作（View 创建 / Sequence 创建或值同步）。Trigger、Function、Procedure 不会自动执行。`,`确认执行 Schema 对象`,{type:'warning',confirmButtonText:'确认执行',cancelButtonText:'取消'});const res=await api<SchemaObjectApplyResult>(`/api/v1/migrations/${detailTask.value.id}/schema-objects/apply`,{method:'POST',body:JSON.stringify({confirm:true})});if(res.failed>0)ElMessage.warning(`执行完成：成功 ${res.applied}，跳过 ${res.skipped}，失败 ${res.failed}`);else ElMessage.success(`执行完成：成功 ${res.applied}，跳过 ${res.skipped}`);await detail(detailTask.value)}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e?.message||String(e))}}
function speed(v:number){return v?`${(v/1024/1024).toFixed(1)} MB/s`:'-'}
function bytes(v:number){if(!v)return'0 B';const u=['B','KB','MB','GB','TB'];let n=v,i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return`${n.toFixed(i>2?2:1)} ${u[i]}`}
function tagType(v:string){return v==='FAILED'||v==='MISMATCH'||v==='ERROR'?'danger':v==='FINISHED'||v==='SUCCESS'||v==='PASS'?'success':v==='WARNING'?'warning':''}
onMounted(async()=>{await Promise.all([load(),loadDS()]);timer=window.setInterval(load,15000);try{socket=openEventSocket();socket.onmessage=(ev)=>{try{const msg=JSON.parse(ev.data);if(msg.type==='task.progress'){const row=items.value.find(x=>x.id===msg.task_id);if(row){Object.assign(row,{status:msg.status,progress:msg.progress,speed_bytes_sec:msg.speed_bytes_sec,target_throughput_mbps:msg.target_throughput_mbps,auto_throughput_enabled:msg.auto_throughput_enabled,completion_sla_seconds:msg.completion_sla_seconds,controller_target_bytes_sec:msg.controller_target_bytes_sec,throughput_controller_reason:msg.throughput_controller_reason,adaptive_hotspot_splits:msg.adaptive_hotspot_splits,adaptive_running_yields:msg.adaptive_running_yields,adaptive_topology_drains:msg.adaptive_topology_drains,adaptive_topology_degraded_yields:msg.adaptive_topology_degraded_yields,controller_auto_probe_pct:msg.controller_auto_probe_pct,controller_sla_headroom_pct:msg.controller_sla_headroom_pct,controller_learning_samples:msg.controller_learning_samples,speed_rows_sec:msg.speed_rows_sec,eta_seconds:msg.eta_seconds,sla_p95_eta_seconds:msg.sla_p95_eta_seconds,sla_p99_eta_seconds:msg.sla_p99_eta_seconds,sla_risk_level:msg.sla_risk_level,sla_risk_reason:msg.sla_risk_reason,rows_migrated:msg.rows_migrated,bytes_migrated:msg.bytes_migrated,effective_parallelism:msg.effective_parallelism,flow_control_level:msg.flow_control_level,cdc_spool_growth_bytes_sec:msg.cdc_spool_growth_bytes_sec,cdc_spool_critical_eta_seconds:msg.cdc_spool_critical_eta_seconds})};if(detailTask.value?.id===msg.task_id)Object.assign(detailTask.value,row||msg)}else if(msg.type==='cdc.metrics'){const row=items.value.find(x=>x.id===msg.task_id);if(row)row.cdc_lag_ms=msg.lag_ms||0;if(detailTask.value?.id===msg.task_id)detailTask.value.cdc_lag_ms=msg.lag_ms||0}}catch{}}}catch{}})
onUnmounted(()=>{if(timer)clearInterval(timer);socket?.close()})
</script>
<template><div>
  <div class="page-title"><div><h1>迁移任务</h1><p>Native 全量、自动建表、Chunk Checkpoint、数据校验、托管 CDC、割接与回切编排</p></div><el-button type="primary" @click="dialog=true">创建迁移任务</el-button></div>
  <div class="panel"><el-table :data="items">
    <el-table-column prop="name" label="任务" min-width="150"/><el-table-column label="链路" min-width="180"><template #default="s">{{dsMap[s.row.source_datasource_id]||s.row.source_datasource_id}} → {{dsMap[s.row.target_datasource_id]||s.row.target_datasource_id}}</template></el-table-column>
    <el-table-column prop="mode" label="模式" width="150"/><el-table-column label="状态" width="175"><template #default="s"><el-tooltip v-if="s.row.last_error" :content="s.row.last_error"><el-tag :type="tagType(s.row.status)">{{s.row.status}}</el-tag></el-tooltip><el-tag v-else :type="tagType(s.row.status)">{{s.row.status}}</el-tag></template></el-table-column>
    <el-table-column label="进度" width="190"><template #default="s"><el-progress :percentage="Math.round(s.row.progress||0)"/><div class="muted">{{s.row.finished_chunks||0}} / {{s.row.total_chunks||0}} chunks</div></template></el-table-column>
    <el-table-column label="已迁移" width="110"><template #default="s">{{bytes(s.row.bytes_migrated)}}</template></el-table-column><el-table-column label="速度" width="105"><template #default="s">{{speed(s.row.speed_bytes_sec)}}</template></el-table-column><el-table-column label="ETA" width="100"><template #default="s">{{s.row.eta_seconds?`${Math.ceil(s.row.eta_seconds/60)} min`:'-'}}</template></el-table-column>
    <el-table-column label="操作" width="330"><template #default="s"><el-button size="small" @click="detail(s.row)">详情</el-button><el-button v-if="s.row.status==='CREATED'" size="small" type="primary" @click="action(s.row.id,'start')">启动</el-button><el-button v-if="s.row.status==='PAUSED'" size="small" type="primary" @click="action(s.row.id,'resume')">恢复</el-button><el-button v-if="s.row.status==='CDC_INITIALIZING'" size="small" type="warning" @click="action(s.row.id,'cdc/started',{})">确认 CDC 已开始捕获</el-button><el-button v-if="['CDC_INITIALIZING','FULL_MIGRATING','CDC_CATCHING_UP','VALIDATING','ROLLBACK_SYNCING'].includes(s.row.status)" size="small" @click="action(s.row.id,'pause')">暂停</el-button><el-button v-if="['FULL_FINISHED','FINISHED'].includes(s.row.status)" size="small" @click="action(s.row.id,'validate')">校验</el-button><el-button v-if="s.row.status==='CDC_CATCHING_UP'" size="small" type="warning" @click="action(s.row.id,'ready-cutover',{max_lag_ms:5000})">准备割接</el-button><el-button v-if="s.row.status==='READY_FOR_CUTOVER'" size="small" type="danger" @click="action(s.row.id,'cutover')">割接</el-button><el-button v-if="s.row.status==='FINISHED' && s.row.mode!=='FULL'" size="small" type="warning" @click="action(s.row.id,'rollback/prepare')">准备回切</el-button><el-button v-if="s.row.status==='ROLLBACK_PREPARING'" size="small" type="warning" @click="action(s.row.id,'rollback/cdc-started',{})">反向 CDC 已启动</el-button><el-button v-if="s.row.status==='ROLLBACK_SYNCING'" size="small" type="warning" @click="action(s.row.id,'rollback/ready',{max_lag_ms:5000})">准备回切</el-button><el-button v-if="s.row.status==='ROLLBACK_READY'" size="small" type="danger" @click="action(s.row.id,'rollback')">执行回切</el-button><el-button v-if="s.row.status==='FAILED'" size="small" type="warning" @click="action(s.row.id,'repair')">修复异常块</el-button><el-button v-if="!['FINISHED','CANCELLED'].includes(s.row.status)" size="small" type="danger" plain @click="action(s.row.id,'cancel')">取消</el-button></template></el-table-column>
  </el-table></div>

  <el-dialog v-model="dialog" title="创建迁移任务" width="720"><el-form label-width="135px">
    <el-form-item label="任务名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="源数据源"><el-select v-model="form.source_datasource_id" style="width:100%"><el-option v-for="d in sources" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="目标数据源"><el-select v-model="form.target_datasource_id" style="width:100%"><el-option v-for="d in sources" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item>
    <el-form-item label="迁移模式"><el-select v-model="form.mode" style="width:100%"><el-option label="全量" value="FULL"/><el-option label="全量 + 增量" value="FULL_AND_INCREMENTAL"/><el-option label="仅增量" value="INCREMENTAL"/></el-select></el-form-item><el-form-item label="迁移内核"><el-alert type="success" :closable="false" title="QMigration Unified Engine（固定）" description="全量切分、流水线、CDC、Checkpoint、校验、流控和回切均由 QMigration 自研统一内核执行；用户不再选择第三方迁移引擎。"/></el-form-item><el-form-item v-if="form.mode!=='FULL'" label="CDC DDL 策略"><el-select v-model="form.cdc_ddl_mode" style="width:100%"><el-option label="拒绝 DDL（默认/安全）" value="REJECT"/><el-option label="同数据库家族 + 同名映射时原样回放" value="SAME_FAMILY"/></el-select><div class="muted">SAME_FAMILY 只允许源/目标属于同一数据库家族，且 Schema、表、字段保持同名映射；异构 DDL 不自动猜测转换。</div></el-form-item><el-form-item v-if="form.mode!=='FULL'" label="CDC 冲突策略"><el-select v-model="form.cdc_conflict_mode" style="width:100%"><el-option label="源端优先（SOURCE_WINS）" value="SOURCE_WINS"/><el-option label="版本列最后写入优先（LAST_WRITE_WINS）" value="LAST_WRITE_WINS"/></el-select><div class="muted">LAST_WRITE_WINS 会按主键锁定目标当前行并比较版本列；源版本更旧或相同则跳过写入但推进 CDC 位点。</div></el-form-item><el-form-item v-if="form.mode!=='FULL' && form.cdc_conflict_mode==='LAST_WRITE_WINS'" label="冲突版本列"><el-input v-model="form.cdc_conflict_column" placeholder="例如 updated_at / version"/><div class="muted">建议使用两端都单调递增/可比较的时间戳或版本号。DELETE 暂不使用 LWW，仍按源端幂等删除。</div></el-form-item><el-form-item v-if="form.mode!=='INCREMENTAL'" label="自动创建目标表"><el-switch v-model="form.auto_create_table"/></el-form-item><el-form-item v-if="form.mode!=='INCREMENTAL'" label="迁移后 DDL"><el-select v-model="form.post_load_ddl_mode" style="width:100%"><el-option label="自动补建二级/唯一索引" value="INDEXES"/><el-option label="索引 + 外键（校验通过后）" value="INDEXES_AND_FOREIGN_KEYS"/><el-option label="不自动处理" value="NONE"/></el-select><div class="muted">为提高全量写入速度，二级索引和外键在数据搬运后处理；外键建议仅在完整校验后启用。</div></el-form-item><el-form-item v-if="form.mode!=='INCREMENTAL'" label="全量完成后校验"><el-switch v-model="form.validation_enabled"/></el-form-item>
    <el-form-item label="Chunk 行数"><el-input-number v-model="form.chunk_rows" :min="1000" :step="10000" style="width:100%"/></el-form-item><el-form-item label="Batch 行数"><el-input-number v-model="form.batch_rows" :min="1" :max="5000" :step="100" style="width:100%"/></el-form-item><el-form-item label="任务并行度"><el-input-number v-model="form.parallelism" :min="1" :max="256" style="width:100%"/></el-form-item><el-form-item label="失败重试"><el-input-number v-model="form.max_retries" :min="1" :max="20" style="width:100%"/></el-form-item>
    <el-form-item label="读取限速 MB/s"><el-input-number v-model="form.read_limit_mbps" :min="0" style="width:100%"/><div class="muted">RC31 起为任务级全局源端预算，会按动态并发精确拆给 Worker。</div></el-form-item><el-form-item label="写入限速 MB/s"><el-input-number v-model="form.write_limit_mbps" :min="0" style="width:100%"/><div class="muted">RC31 起为任务级全局目标端预算，不再按 Worker 数量放大。</div></el-form-item><el-form-item label="目标吞吐 MB/s"><el-input-number v-model="form.target_throughput_mbps" :min="0" style="width:100%"/><div class="muted">手工任务级全局目标。与 AUTO/SLA 模式互斥；0 表示不使用手工目标。</div></el-form-item><el-form-item label="自动吞吐寻优"><el-switch v-model="form.auto_throughput_enabled"/><div class="muted">根据 EWMA 吞吐和 NORMAL/WARN/CRITICAL 压力自动调整 pacing 目标与并发。</div></el-form-item><el-form-item label="完成 SLA 秒"><el-input-number v-model="form.completion_sla_seconds" :min="0" style="width:100%"/><div class="muted">从 Full 首次执行开始计算剩余完成时间；控制器按剩余工作量反推所需吞吐。与手工目标/AUTO 互斥。</div></el-form-item><el-form-item label="Rows/s 限速"><el-input-number v-model="form.rows_limit_per_sec" :min="0" style="width:100%"/></el-form-item><el-form-item label="QPS 限速"><el-input-number v-model="form.qps_limit" :min="0" style="width:100%"/></el-form-item><el-form-item label="限速时区"><el-input v-model="form.rate_limit_timezone" placeholder="Local / Asia/Shanghai"/></el-form-item><el-form-item label="分时限速策略"><el-input v-model="rateWindowsJson" type="textarea" :rows="4" placeholder='[{"start":"08:00","end":"18:00","read_limit_mbps":100,"write_limit_mbps":100,"target_throughput_mbps":80,"rows_per_second":50000,"qps":200,"parallelism":8}]'/><div class="muted">支持跨午夜时间段；命中窗口后可覆盖 MB/s、目标吞吐、Rows/s、QPS 和并行度。</div></el-form-item><el-form-item label="Worker 亲和策略"><el-select v-model="form.worker_affinity" style="width:100%"><el-option label="PREFERRED（优先本地，无匹配可回退）" value="PREFERRED"/><el-option label="REQUIRED（必须匹配标签）" value="REQUIRED"/></el-select></el-form-item><el-form-item label="Worker 标签选择"><el-input v-model="workerSelectorJson" placeholder='{"zone":"az-a","network":"migration"}'/><div class="muted">可按 zone / rack / region / network 等 Worker 标签做拓扑亲和；留空表示不限制。</div></el-form-item><el-form-item label="值转换策略"><el-input v-model="transformRulesJson" type="textarea" :rows="6" placeholder='[ { "source_schema":"app", "source_table":"orders", "column":"created_at", "action":"ZERO_DATE_TO_NULL" }, { "column":"name", "action":"TRIM" } ]'/><div class="muted">QMigration Transform Policy DSL 在统一 Row Pipeline 内执行，不拼接用户 SQL。支持 TRIM、LOWER、UPPER、EMPTY_TO_NULL、NULL_TO_VALUE、REPLACE_LITERAL、ZERO_DATE_TO_NULL、ZERO_DATE_TO_VALUE、JSON_COMPACT；规则按声明顺序执行。</div></el-form-item><el-form-item label="高级表/字段映射"><el-input v-model="tableMappingsJson" type="textarea" :rows="6" placeholder='[ { "source_schema":"app", "source_table":"orders", "target_schema":"biz", "target_table":"orders_new", "columns":[{"source_column":"order_id","target_column":"id"}] } ]'/><div class="muted">留空则迁移源默认库全部表；支持 Schema/表/字段映射，以及 split_strategy=AUTO|PRIMARY_KEY_RANGE|UNIQUE_KEY_RANGE|HASH|PARTITION|CUSTOM_SQL、partitions、hash_buckets、custom_where。</div></el-form-item>
  </el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">创建</el-button></template></el-dialog>

  <el-dialog v-model="detailDialog" :title="`任务详情 - ${detailTask?.name||''}`" width="1180"><el-descriptions v-if="detailTask" :column="4" border><el-descriptions-item label="状态">{{detailTask.status}}<span v-if="detailTask.paused_from_status" class="muted">（暂停自 {{detailTask.paused_from_status}}）</span></el-descriptions-item><el-descriptions-item label="进度">{{(detailTask.progress||0).toFixed(1)}}%</el-descriptions-item><el-descriptions-item label="Chunks">{{detailTask.finished_chunks}} / {{detailTask.total_chunks}}</el-descriptions-item><el-descriptions-item label="Rows">{{detailTask.rows_migrated}}</el-descriptions-item><el-descriptions-item label="Rows/s">{{detailTask.speed_rows_sec||0}}</el-descriptions-item><el-descriptions-item label="目标吞吐">{{detailTask.target_throughput_mbps?`${detailTask.target_throughput_mbps} MB/s`:detailTask.controller_target_bytes_sec?`${(detailTask.controller_target_bytes_sec/1024/1024).toFixed(1)} MB/s（Controller）`:'-'}}</el-descriptions-item><el-descriptions-item label="吞吐利用率">{{(detailTask.target_throughput_mbps||detailTask.controller_target_bytes_sec)?`${Math.round((detailTask.speed_bytes_sec||0)/((detailTask.target_throughput_mbps||0)*1024*1024+(detailTask.target_throughput_mbps?0:(detailTask.controller_target_bytes_sec||0)))*100)}%`:'-'}}</el-descriptions-item><el-descriptions-item label="ETA">{{detailTask.eta_seconds?`${Math.ceil(detailTask.eta_seconds/60)} min`:'-'}}</el-descriptions-item><el-descriptions-item label="P95 ETA">{{detailTask.sla_p95_eta_seconds?`${Math.ceil(detailTask.sla_p95_eta_seconds/60)} min`:'-'}}</el-descriptions-item><el-descriptions-item label="P99 ETA">{{detailTask.sla_p99_eta_seconds?`${Math.ceil(detailTask.sla_p99_eta_seconds/60)} min`:'-'}}</el-descriptions-item><el-descriptions-item label="SLA 尾延迟风险"><el-tag :type="detailTask.sla_risk_level==='CRITICAL'?'danger':detailTask.sla_risk_level==='WARN'?'warning':'success'">{{detailTask.sla_risk_level||'NONE'}}</el-tag><span v-if="detailTask.sla_risk_reason" class="muted"> {{detailTask.sla_risk_reason}}</span></el-descriptions-item><el-descriptions-item label="动态并发">{{detailTask.effective_parallelism||detailTask.parallelism||'-'}} / {{detailTask.parallelism||'-'}}</el-descriptions-item><el-descriptions-item label="性能控制">{{detailTask.completion_sla_seconds?`SLA ${detailTask.completion_sla_seconds}s`:detailTask.auto_throughput_enabled?'AUTO':detailTask.target_throughput_mbps?'MANUAL':'OFF'}}</el-descriptions-item><el-descriptions-item label="控制器原因" :span="2">{{detailTask.throughput_controller_reason||'-'}}</el-descriptions-item><el-descriptions-item label="热点拆分">{{detailTask.adaptive_hotspot_splits||0}}</el-descriptions-item><el-descriptions-item label="运行中让出">{{detailTask.adaptive_running_yields||0}}</el-descriptions-item><el-descriptions-item label="拓扑熔断让出">{{detailTask.adaptive_topology_drains||0}}</el-descriptions-item><el-descriptions-item label="拓扑降级让出">{{detailTask.adaptive_topology_degraded_yields||0}}</el-descriptions-item><el-descriptions-item label="故障域让出">{{detailTask.adaptive_fault_domain_yields||0}}</el-descriptions-item><el-descriptions-item label="AUTO Probe">{{detailTask.controller_auto_probe_pct?`${detailTask.controller_auto_probe_pct}%`:'默认 125%'}}</el-descriptions-item><el-descriptions-item label="SLA Headroom">{{detailTask.controller_sla_headroom_pct?`${detailTask.controller_sla_headroom_pct}%`:'默认 110%'}}</el-descriptions-item><el-descriptions-item label="学习样本">{{detailTask.controller_learning_samples||0}}</el-descriptions-item><el-descriptions-item label="Task 流控"><el-tag :type="detailTask.flow_control_level==='CRITICAL'?'danger':detailTask.flow_control_level==='WARN'?'warning':'success'">{{detailTask.flow_control_level||'NORMAL'}}</el-tag><span v-if="detailTask.flow_control_reason" class="muted"> {{detailTask.flow_control_reason}}</span></el-descriptions-item><el-descriptions-item label="Spool 增长">{{((detailTask.cdc_spool_growth_bytes_sec||0)/1024/1024).toFixed(2)}} MB/s</el-descriptions-item><el-descriptions-item label="Spool 临界 ETA">{{detailTask.cdc_spool_critical_eta_seconds?`${detailTask.cdc_spool_critical_eta_seconds}s`:'-'}}</el-descriptions-item><el-descriptions-item label="CDC Lag">{{detailTask.cdc_lag_ms||0}} ms</el-descriptions-item><el-descriptions-item label="Sequence 同步">{{detailTask.sequence_synced_at?new Date(detailTask.sequence_synced_at).toLocaleString():'-'}}</el-descriptions-item></el-descriptions>
    <el-tabs v-model="activeTab" style="margin-top:18px"><el-tab-pane label="表进度" name="tables"><el-table :data="detailTables" max-height="360"><el-table-column label="源表"><template #default="s">{{s.row.source_schema}}.{{s.row.source_table}}</template></el-table-column><el-table-column label="目标表"><template #default="s">{{s.row.target_schema}}.{{s.row.target_table}}</template></el-table-column><el-table-column label="迁移内核" width="150"><template #default>QMigration</template></el-table-column><el-table-column prop="primary_key" label="PK" width="120"/><el-table-column label="源拓扑" min-width="190"><template #default="s"><el-tag v-for="p in (s.row.topology||[])" :key="p.id" type="info" style="margin:2px">{{p.kind}} · {{Object.entries(p.labels||{}).map(([k,v])=>`${k}=${v}`).join(',')}}</el-tag><span v-if="!(s.row.topology||[]).length" class="muted">未发现/不支持</span></template></el-table-column><el-table-column prop="status" label="状态" width="110"/><el-table-column label="Chunks" width="120"><template #default="s">{{s.row.finished_chunks}} / {{s.row.total_chunks}}</template></el-table-column><el-table-column prop="rows_migrated" label="Rows" width="120"/><el-table-column label="画像吞吐" width="125"><template #default="s">{{((s.row.profile_bytes_per_sec||0)/1024/1024).toFixed(1)}} MB/s</template></el-table-column><el-table-column label="推荐 Chunk" width="125"><template #default="s">{{s.row.recommended_chunk_rows||'-'}}</template></el-table-column><el-table-column label="画像样本" width="100"><template #default="s">{{s.row.performance_samples||0}}</template></el-table-column><el-table-column label="拓扑健康" min-width="180"><template #default="s"><span v-if="Object.keys(s.row.topology_performance||{}).length"><el-tag v-for="(p,id) in (s.row.topology_performance||{})" :key="id" :type="p.health==='CIRCUIT_OPEN'?'danger':p.health==='DEGRADED'||p.health==='HALF_OPEN'?'warning':'success'" style="margin:2px">{{id}} · {{p.health||'HEALTHY'}}<span v-if="p.health==='DEGRADED' && (p.recovery_concurrency_cap||0)>0"> · cap {{p.recovery_concurrency_cap}} · good {{p.good_streak||0}}</span></el-tag></span><span v-else class="muted">-</span></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="Chunk" name="chunks"><el-table :data="detailChunks" max-height="400"><el-table-column prop="chunk_no" label="#" width="60"/><el-table-column prop="split_type" label="切分" width="180"/><el-table-column label="分片参数" min-width="180"><template #default="s"><span v-if="s.row.partition_name">Partition={{s.row.partition_name}}</span><span v-else-if="s.row.hash_buckets">Hash={{s.row.hash_bucket}}/{{s.row.hash_buckets}}</span><span v-else-if="s.row.custom_where" class="muted">{{s.row.custom_where}}</span><span v-else>-</span></template></el-table-column><el-table-column label="范围 / Cursor" min-width="270"><template #default="s"><span v-if="s.row.split_type?.includes('KEYSET')" class="muted">[{{s.row.start_cursor_json||'-∞'}}, {{s.row.end_cursor_json||'+∞'}}) · {{s.row.cursor_json||'尚未产生 Cursor'}}</span><span v-else>[{{s.row.start}}, {{s.row.end}}]</span></template></el-table-column><el-table-column label="拓扑 Hint" min-width="180"><template #default="s"><span v-if="s.row.topology_id"><el-tag type="info">{{s.row.topology_kind}}</el-tag> {{Object.entries(s.row.placement_hint||{}).map(([k,v])=>`${k}=${v}`).join(',')}}</span><span v-else class="muted">-</span></template></el-table-column><el-table-column prop="status" label="状态" width="110"/><el-table-column prop="worker_id" label="Worker" min-width="130"/><el-table-column prop="rows_written" label="Rows" width="100"/><el-table-column label="读/写延迟" width="125"><template #default="s">{{s.row.last_read_ms||0}} / {{s.row.last_write_ms||0}} ms</template></el-table-column><el-table-column label="流控" width="105"><template #default="s"><el-tag v-if="s.row.backpressure_level" :type="s.row.backpressure_level==='CRITICAL'?'danger':s.row.backpressure_level==='WARN'?'warning':'success'">{{s.row.backpressure_level}}</el-tag><span v-else>-</span></template></el-table-column><el-table-column prop="retry_count" label="Retry" width="80"/><el-table-column prop="last_error" label="错误" min-width="200" show-overflow-tooltip/></el-table></el-tab-pane>
      <el-tab-pane label="预检查" name="precheck"><el-table :data="prechecks"><el-table-column prop="name" label="检查项" width="180"/><el-table-column label="结果" width="120"><template #default="s"><el-tag :type="tagType(s.row.level)">{{s.row.level}}</el-tag></template></el-table-column><el-table-column prop="message" label="说明"/></el-table></el-tab-pane>
      <el-tab-pane label="兼容性评估" name="assessment"><div v-if="assessment"><el-descriptions :column="4" border style="margin-bottom:14px"><el-descriptions-item label="可启动"><el-tag :type="assessment.can_start?'success':'danger'">{{assessment.can_start?'YES':'NO'}}</el-tag></el-descriptions-item><el-descriptions-item label="兼容">{{assessment.compatible}}</el-descriptions-item><el-descriptions-item label="警告">{{assessment.warnings}}</el-descriptions-item><el-descriptions-item label="不支持">{{assessment.unsupported}}</el-descriptions-item></el-descriptions><el-table :data="assessment.findings" max-height="400"><el-table-column prop="object_type" label="对象" width="120"/><el-table-column prop="source_object" label="源对象" min-width="170"/><el-table-column prop="target_object" label="目标对象" min-width="170"/><el-table-column label="级别" width="120"><template #default="s"><el-tag :type="s.row.level==='UNSUPPORTED'?'danger':s.row.level==='WARNING'?'warning':'success'">{{s.row.level}}</el-tag></template></el-table-column><el-table-column prop="code" label="代码" width="190"/><el-table-column prop="message" label="说明" min-width="280"/></el-table></div></el-tab-pane>
      <el-tab-pane label="Schema 对象" name="schema-objects"><div v-if="schemaObjectPlan"><el-alert type="info" :closable="false" title="自动执行范围保持保守：View 按依赖拓扑创建；PostgreSQL standalone/SERIAL Sequence 可同步，IDENTITY 只在目标语义已存在时同步状态；Trigger / Function / Procedure 保持 MANUAL。"/><el-descriptions :column="3" border style="margin:14px 0"><el-descriptions-item label="安全动作"><el-tag type="success">{{schemaObjectPlan.safe_actions}}</el-tag></el-descriptions-item><el-descriptions-item label="人工处理"><el-tag type="warning">{{schemaObjectPlan.manual}}</el-tag></el-descriptions-item><el-descriptions-item label="已存在/跳过">{{schemaObjectPlan.skipped}}</el-descriptions-item></el-descriptions><div style="margin-bottom:12px"><el-button v-if="schemaObjectPlan.safe_actions>0" type="primary" @click="applySafeSchemaObjects">执行安全对象</el-button></div><el-table :data="schemaObjectPlan.items" max-height="420"><el-table-column label="类型" width="110"><template #default="s"><el-tag>{{s.row.source.type}}</el-tag></template></el-table-column><el-table-column label="源对象" min-width="170"><template #default="s">{{s.row.source.schema}}.{{s.row.source.name}}</template></el-table-column><el-table-column label="目标对象" min-width="170"><template #default="s">{{s.row.target_schema}}.{{s.row.target_name}}</template></el-table-column><el-table-column label="动作" width="150"><template #default="s"><el-tag :type="s.row.action==='APPLY_SAFE'||s.row.action==='SYNC_SEQUENCE'?'success':s.row.action==='MANUAL'?'warning':'info'">{{s.row.action}}</el-tag></template></el-table-column><el-table-column label="依赖" min-width="180"><template #default="s"><span v-if="s.row.source.type==='VIEW'">{{s.row.source.dependencies_known===false?'依赖未知':(s.row.source.dependencies||[]).join(', ')||'-'}}</span><span v-else>-</span></template></el-table-column><el-table-column label="绑定 / 关联" min-width="210"><template #default="s"><span v-if="s.row.source.type==='SEQUENCE'">{{s.row.source.binding_known===false?'绑定未知':((s.row.source.definition||'STANDALONE')+(s.row.source.related_to?' · '+s.row.source.related_to:'')+(s.row.target_related_to?' → '+s.row.target_related_to:''))}}</span><span v-else-if="s.row.source.related_to">{{s.row.source.related_to}}</span><span v-else>-</span></template></el-table-column><el-table-column label="目标存在" width="100"><template #default="s">{{s.row.target_exists?'YES':'NO'}}</template></el-table-column><el-table-column prop="reason" label="说明" min-width="300"/></el-table></div><el-empty v-else description="当前数据源的 QMigration Schema Connector 尚未实现该对象目录。"/></el-tab-pane>
      <el-tab-pane label="数据校验" name="validation"><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px"><el-button size="small" @click="downloadValidationReport('html')">验收报告 HTML</el-button><el-button size="small" @click="downloadValidationReport('pdf')">验收报告 PDF</el-button><el-button size="small" @click="downloadValidationReport('json')">证据 JSON</el-button><el-button size="small" @click="downloadValidationReport('manifest')">签名 Manifest</el-button><el-button size="small" @click="downloadValidationPublicKey">Ed25519 公钥</el-button><el-button size="small" @click="showValidationArchiveRegistry">归档登记</el-button><el-button size="small" type="primary" @click="archiveValidationReport">归档 S3 / WORM</el-button></div><el-alert type="info" :closable="false" title="验收报告基于不可变 Validation Archive 生成；JSON/HTML/PDF 均带 SHA-256，并可用 Ed25519 做公开可验证签名（HMAC 可继续并用）。S3 Object Lock 配置开启时，服务端会回读验证 WORM 后再登记 URI、Manifest SHA 和公钥指纹。" style="margin-bottom:12px"/><el-table :data="validations" max-height="400"><el-table-column prop="chunk_id" label="Chunk" min-width="150"/><el-table-column label="状态" width="110"><template #default="s"><el-tag :type="tagType(s.row.status)">{{s.row.status}}</el-tag></template></el-table-column><el-table-column prop="source_rows" label="源行数" width="100"/><el-table-column prop="target_rows" label="目标行数" width="100"/><el-table-column prop="source_checksum" label="源 Checksum" min-width="150"/><el-table-column prop="target_checksum" label="目标 Checksum" min-width="150"/><el-table-column prop="last_error" label="错误" min-width="180"/></el-table></el-tab-pane>
      <el-tab-pane label="CDC" name="cdc"><el-alert type="info" :closable="false" title="Full+CDC 在全量阶段会把源事务先压缩、加密并持久化到 QMigration Durable Spool；Spool 成功后才 ACK 源端。全量/校验完成后按事务顺序 Drain，目标 Apply 成功后再推进正式 Checkpoint。"/><el-descriptions :column="4" border style="margin-top:14px"><el-descriptions-item label="Spool 事务"><el-tag :type="cdcSpool.pending_transactions?'warning':'success'">{{cdcSpool.pending_transactions}}</el-tag></el-descriptions-item><el-descriptions-item label="Spool Events">{{cdcSpool.pending_events}}</el-descriptions-item><el-descriptions-item label="Spool 容量">{{bytes(cdcSpool.pending_bytes)}}</el-descriptions-item><el-descriptions-item label="操作"><el-button size="small" :disabled="!cdcSpool.pending_transactions" @click="drainSpool">手动 Drain</el-button></el-descriptions-item><el-descriptions-item label="首位点" :span="2">{{cdcSpool.first_position||'-'}}</el-descriptions-item><el-descriptions-item label="末位点" :span="2">{{cdcSpool.last_position||'-'}}</el-descriptions-item><el-descriptions-item label="Spool 后端">{{cdcSpool.storage_backend||'metadata'}}</el-descriptions-item><el-descriptions-item label="磁盘水位"><el-tag :type="cdcSpool.storage_level==='CRITICAL'?'danger':cdcSpool.storage_level==='WARN'?'warning':'success'">{{cdcSpool.storage_level||'NORMAL'}}</el-tag> {{(cdcSpool.storage_used_pct||0).toFixed(1)}}%</el-descriptions-item><el-descriptions-item label="磁盘可用" :span="2">{{bytes(cdcSpool.storage_free_bytes||0)}} / {{bytes(cdcSpool.storage_capacity_bytes||0)}}</el-descriptions-item><el-descriptions-item label="Validation Barrier" :span="2">{{detailTask?.validation_barrier_position_type||'-'}} {{detailTask?.validation_barrier_position_value||'-'}}</el-descriptions-item><el-descriptions-item label="Barrier 捕获时间" :span="2">{{detailTask?.validation_barrier_captured_at||'-'}}</el-descriptions-item></el-descriptions><el-table :data="cdc" style="margin-top:14px"><el-table-column prop="direction" label="方向" width="90"/><el-table-column prop="position_type" label="位点类型" width="130"/><el-table-column prop="position_value" label="位点" min-width="180"/><el-table-column prop="lag_ms" label="Lag(ms)" width="110"/><el-table-column prop="events_total" label="Events" width="110"/><el-table-column prop="events_pending" label="Pending" width="110"/><el-table-column prop="recorded_at" label="时间" width="200"/></el-table></el-tab-pane>
      <el-tab-pane :label="`CDC DLQ${dlq.filter(x=>x.status!=='RESOLVED').length?` (${dlq.filter(x=>x.status!=='RESOLVED').length})`:''}`" name="cdc-dlq"><el-alert type="warning" :closable="false" title="CDC Apply 失败会保留源位点。COMMIT_UNCERTAIN 表示目标 COMMIT 结果未知，自动重放被禁止；必须先确认实际提交结果。REPLAY_REQUIRED 表示已确认未提交但受控重放尚未成功，必须显式重放成功后才能继续该方向 CDC。"/><el-table :data="dlq" style="margin-top:14px" max-height="400"><el-table-column prop="direction" label="方向" width="90"/><el-table-column label="状态" width="150"><template #default="s"><el-tag :type="s.row.status==='RESOLVED'?'success':(s.row.status==='COMMIT_UNCERTAIN'||s.row.status==='REPLAY_REQUIRED')?'warning':'danger'">{{s.row.status}}</el-tag></template></el-table-column><el-table-column prop="position_type" label="位点类型" width="120"/><el-table-column prop="position_value" label="位点" min-width="190" show-overflow-tooltip/><el-table-column prop="retry_count" label="Retry" width="80"/><el-table-column prop="last_error" label="最近错误" min-width="260" show-overflow-tooltip/><el-table-column prop="updated_at" label="更新时间" width="190"/><el-table-column label="操作" width="250"><template #default="s"><el-button v-if="s.row.status==='OPEN'||s.row.status==='REPLAY_REQUIRED'" size="small" type="warning" @click="replayDLQ(s.row)">{{s.row.status==='REPLAY_REQUIRED'?'恢复重放':'重放'}}</el-button><template v-else-if="s.row.status==='COMMIT_UNCERTAIN'"><el-button size="small" type="success" @click="resolveCommit(s.row,'COMMITTED')">已提交</el-button><el-button size="small" type="danger" @click="resolveCommit(s.row,'NOT_COMMITTED')">未提交</el-button></template></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane :label="'CDC 冲突'+(conflicts.length?' ('+conflicts.length+')':'')" name="cdc-conflicts"><el-alert type="info" :closable="false" title="LAST_WRITE_WINS 决策只保存主键指纹，不保存业务主键明文。TARGET_KEPT 表示目标版本较新/相同，SOURCE_APPLIED 表示源版本较新并已写入。"/><el-table :data="conflicts" style="margin-top:14px" max-height="400"><el-table-column prop="direction" label="方向" width="90"/><el-table-column prop="source_schema" label="Schema" width="120"/><el-table-column prop="source_table" label="表" width="150"/><el-table-column prop="key_fingerprint" label="Key 指纹" width="190"/><el-table-column prop="decision" label="决策" width="150"><template #default="s"><el-tag :type="s.row.decision==='TARGET_KEPT'?'warning':'success'">{{s.row.decision}}</el-tag></template></el-table-column><el-table-column prop="source_version" label="源版本" min-width="130"/><el-table-column prop="target_version" label="目标版本" min-width="130"/><el-table-column prop="position_value" label="位点" min-width="180" show-overflow-tooltip/><el-table-column prop="created_at" label="时间" width="190"/></el-table></el-tab-pane>
      <el-tab-pane label="任务日志" name="logs"><el-table :data="taskLogs" max-height="420"><el-table-column prop="created_at" label="时间" width="190"/><el-table-column prop="level" label="级别" width="90"><template #default="s"><el-tag :type="s.row.level==='ERROR'?'danger':s.row.level==='WARN'?'warning':'info'">{{s.row.level}}</el-tag></template></el-table-column><el-table-column prop="worker_id" label="Worker" width="130"/><el-table-column prop="chunk_id" label="Chunk" width="150"/><el-table-column prop="message" label="消息" min-width="420"/></el-table></el-tab-pane><el-tab-pane label="CDC Runtime" name="engine-jobs"><el-table :data="engineJobs" max-height="400"><el-table-column prop="direction" label="方向" width="100"/><el-table-column label="运行时" width="130"><template #default>QMigration</template></el-table-column><el-table-column prop="kind" label="类型" width="90"/><el-table-column label="状态" width="150"><template #default="s"><el-tag :type="tagType(s.row.status)">{{s.row.status}}</el-tag></template></el-table-column><el-table-column prop="worker_id" label="Worker" min-width="140"/><el-table-column prop="retry_count" label="Retry" width="80"/><el-table-column prop="last_error" label="最近错误" min-width="220" show-overflow-tooltip/><el-table-column prop="updated_at" label="更新时间" width="190"/></el-table></el-tab-pane>
    </el-tabs>
  </el-dialog>
</div></template>
